typedef void (*fun_3c2e)(double*, double*, double, double, double, double, double, double[3], double[3], double, double, double);
static fun_3c2e XINT_FUNC_LIST[]={
    xint_3c2e_0_0,xint_3c2e_0_1,xint_3c2e_0_2,xint_3c2e_0_3,xint_3c2e_0_4,xint_3c2e_0_5,
    xint_3c2e_1_0,xint_3c2e_1_1,xint_3c2e_1_2,xint_3c2e_1_3,xint_3c2e_1_4,xint_3c2e_1_5,
    xint_3c2e_2_0,xint_3c2e_2_1,xint_3c2e_2_2,xint_3c2e_2_3,xint_3c2e_2_4,xint_3c2e_2_5,
    xint_3c2e_3_0,xint_3c2e_3_1,xint_3c2e_3_2,xint_3c2e_3_3,xint_3c2e_3_4,xint_3c2e_3_5,
    xint_3c2e_4_0,xint_3c2e_4_1,xint_3c2e_4_2,xint_3c2e_4_3,xint_3c2e_4_4,xint_3c2e_4_5,
    xint_3c2e_5_0,xint_3c2e_5_1,xint_3c2e_5_2,xint_3c2e_5_3,xint_3c2e_5_4,xint_3c2e_5_5,
    xint_3c2e_6_0,xint_3c2e_6_1,xint_3c2e_6_2,xint_3c2e_6_3,xint_3c2e_6_4,xint_3c2e_6_5,
    xint_3c2e_7_0,xint_3c2e_7_1,xint_3c2e_7_2,xint_3c2e_7_3,xint_3c2e_7_4,xint_3c2e_7_5,
    xint_3c2e_8_0,xint_3c2e_8_1,xint_3c2e_8_2,xint_3c2e_8_3,xint_3c2e_8_4,xint_3c2e_8_5
};

void xint_3c2e(Vector buf, int shlij, int shla, xint_info xint)
{
	const mol_info mol = xint->mol;
	const shell_pair shp = &mol->pair->shp[shlij];
	const bas_info bas = mol->bas;
	const bas_info aux = xint->aux;
	int shli = shp->shli, shlj = shp->shlj;
	const Vector coei = get_bas_coe(shli, bas);
	const Vector coej = get_bas_coe(shlj, bas);
	const Vector coea = get_bas_coe(shla, aux);
	const Vector expa = get_bas_exp(shla, aux);
	int li = shp->li, lj = shp->lj, lk = aux(ANGULAR_VAL, shla);
	int di = shp->di, dj = shp->dj, dk = aux(NPRIM_VAL, shla);
	double rho;
	double xi, half_xi_, gamma, coe, coe1, coe2, *P, *PA, *AB, PC[3], *C, K_ab, x, PC_dist2, tmp;
	int begin_index, end_index;
	int len, len0, tol_len;
	static int vrr_len[] = {
    1, 0, 0, 0, 0,
    3, 9, 0, 0, 0,
    6, 16, 31, 0, 0,
    10, 25, 46, 74, 0,
    15, 36, 64, 100, 145};
	static const int buf_list[] = {1, 4, 10, 20, 35, 56, 84, 120, 165, 220};
	static const int vrr_len_list[] = {1, 3, 6, 10, 15, 21, 4, 12, 24, 40, 60, 84, 10, 30, 60, 100, 150, 210, 20, 60, 120, 200, 300, 420, 35, 105, 210, 350, 525, 735, 56, 168, 336, 560, 840, 1176, 84, 252, 504, 840, 1260, 1764, 120, 360, 720, 1200, 1800, 2520, 165, 495, 990, 1650, 2475, 3465};
	fun_3c2e hgp3c2e_vrr = XINT_FUNC_LIST[6 * (li+lj) + lk];
	C = get_atm_coord(aux(ATOM_IND, shla), mol->atm);
	AB = shp->AB;
	end_index = buf_list[li + lj];
	len = vrr_len[5 * li + lj];
	begin_index = end_index - len;
	len0 = (li + 1) * (li + 2) * (lj + 1) * (lj + 2) / 4;
	int ll = vrr_len_list[lk + 6 * (li + lj)] + 1;
	memset(xint->cache, 0, sizeof(double) * ll);
	for (int i = 0, uu = 0; i < di; ++i)
		for (int j = 0; j < dj; ++j, ++uu)
		{
			P = &shp->P[uu * 3];
			PA = &shp->PA[uu * 3];
			PC[0] = P[0] - C[0];
			PC[1] = P[1] - C[1];
			PC[2] = P[2] - C[2];
			PC_dist2 = PC[0] * PC[0] + PC[1] * PC[1] + PC[2] * PC[2];
			xi = shp->xi[uu];
			half_xi_ = shp->half_xi_[uu];
			K_ab = shp->K_ab[uu * 4 + 3];
			for (int k = 0; k < dk; k++)
			{
				gamma = expa[k];
				rho = xi * gamma / (gamma + xi);
				coe = rho / xi;
				coe1 = rho / gamma;
				coe2 = coe1 * half_xi_;
				tmp = MY_PI * MY_PI * K_ab / sqrt(xi + gamma) / (xi * gamma) * coei[i] * coej[j] * coea[k];
				x = rho;
				hgp3c2e_vrr(xint->cache, &xint->cache[ll], half_xi_, gamma, coe, coe1, coe2, PA, PC, x, PC_dist2, tmp);
			}
		}
	for (int k = 0; k < (lk + 1) * (lk + 2) / 2; k++)
	{
		memcpy(&xint->cache[ll], &xint->cache[end_index * k + begin_index], sizeof(double) * len);
		xint_hrr(&buf[len0 * k], &xint->cache[ll], li, lj, AB);
	}
	return;
}
